package com.kotsafe.p2p;

import java.security.SecureRandom;
import java.util.Base64;

/**
 * Foreground-service health state for a client Personal Gateway tunnel.
 *
 * The transport invokes this after its authenticated handshake, every
 * encrypted heartbeat, each tunnel byte update, and an encrypted egress
 * response. The exit-IP response is accepted only when it contains the
 * outstanding one-use nonce generated by this device.
 */
public final class GatewayHealthMonitor {
    public enum Path { DIRECT, RELAY }
    public enum Status { DISCONNECTED, CONNECTED_UNVERIFIED, VERIFIED, BLOCKED, ERROR }

    public static final long HEARTBEAT_TIMEOUT_MS = 30_000L;
    public static final long EGRESS_CHECK_TIMEOUT_MS = 20_000L;
    private static final SecureRandom RANDOM = new SecureRandom();

    public static final class Snapshot {
        public final Status status;
        public final Path path;
        public final String exitIp;
        public final long sentBytes;
        public final long receivedBytes;
        public final String detail;

        private Snapshot(Status status, Path path, String exitIp, long sentBytes,
                         long receivedBytes, String detail) {
            this.status = status;
            this.path = path;
            this.exitIp = exitIp;
            this.sentBytes = sentBytes;
            this.receivedBytes = receivedBytes;
            this.detail = detail;
        }
    }

    private final boolean killSwitch;
    private Status status = Status.DISCONNECTED;
    private Path path;
    private String exitIp;
    private String pendingNonce;
    private long heartbeatAt;
    private long challengeAt;
    private long sentBytes;
    private long receivedBytes;
    private String detail = "Disconnected";

    public GatewayHealthMonitor(boolean killSwitch) {
        this.killSwitch = killSwitch;
    }

    public synchronized void onTunnelConnected(Path activePath, long nowMs) {
        if (activePath == null) throw new IllegalArgumentException("path is required");
        path = activePath;
        heartbeatAt = nowMs;
        pendingNonce = null;
        exitIp = null;
        sentBytes = 0L;
        receivedBytes = 0L;
        status = Status.CONNECTED_UNVERIFIED;
        detail = "Tunnel connected; verifying exit IP";
    }

    /** Returns a one-use nonce for an encrypted egress-check control frame. */
    public synchronized String beginEgressCheck(long nowMs) {
        if (status != Status.CONNECTED_UNVERIFIED && status != Status.VERIFIED) {
            throw new IllegalStateException("tunnel is not connected");
        }
        byte[] bytes = new byte[24];
        RANDOM.nextBytes(bytes);
        pendingNonce = Base64.getUrlEncoder().withoutPadding().encodeToString(bytes);
        challengeAt = nowMs;
        return pendingNonce;
    }

    /** Invoke only when the encrypted response returned through the active tunnel. */
    public synchronized boolean onEgressCheckResult(String nonce, String observedExitIp, long nowMs) {
        if (pendingNonce == null || !pendingNonce.equals(nonce) || !isIpLiteral(observedExitIp)) return false;
        pendingNonce = null;
        exitIp = observedExitIp;
        heartbeatAt = nowMs;
        status = Status.VERIFIED;
        detail = "Exit IP verified";
        return true;
    }

    public synchronized void onHeartbeat(long nowMs) {
        if (status == Status.CONNECTED_UNVERIFIED || status == Status.VERIFIED) heartbeatAt = nowMs;
    }

    public synchronized void onTunnelBytes(long toExit, long fromExit) {
        if (toExit < 0 || fromExit < 0) throw new IllegalArgumentException("byte counts cannot decrease");
        sentBytes += toExit;
        receivedBytes += fromExit;
    }

    /** Called periodically by the foreground service. Returns true when state changed. */
    public synchronized boolean tick(long nowMs) {
        if (status != Status.CONNECTED_UNVERIFIED && status != Status.VERIFIED) return false;
        if (nowMs - heartbeatAt > HEARTBEAT_TIMEOUT_MS) {
            unavailable("Exit heartbeat timed out");
            return true;
        }
        if (pendingNonce != null && nowMs - challengeAt > EGRESS_CHECK_TIMEOUT_MS) {
            unavailable("Exit IP verification timed out");
            return true;
        }
        return false;
    }

    public synchronized void onTransportError(String reason) {
        unavailable(reason == null || reason.trim().isEmpty() ? "Tunnel transport failed" : reason);
    }

    /** Use this decision at the VPN/TUN routing boundary before direct egress. */
    public synchronized boolean shouldBlockProtectedTraffic() {
        return killSwitch && status != Status.VERIFIED;
    }

    public synchronized Snapshot snapshot() {
        return new Snapshot(status, path, exitIp, sentBytes, receivedBytes, detail);
    }

    private void unavailable(String reason) {
        pendingNonce = null;
        status = killSwitch ? Status.BLOCKED : Status.ERROR;
        detail = reason;
    }

    private static boolean isIpLiteral(String value) {
        if (value == null || value.length() < 3 || value.length() > 45) return false;
        if (value.indexOf(':') >= 0) {
            return value.matches("[0-9a-fA-F:.]+") && !value.contains(":::") &&
                    (!value.startsWith(":") || value.startsWith("::")) &&
                    (!value.endsWith(":") || value.endsWith("::"));
        }
        String[] parts = value.split("\\.", -1);
        if (parts.length != 4) return false;
        for (String part : parts) {
            try {
                if (part.isEmpty() || (part.length() > 1 && part.startsWith("0"))) return false;
                int number = Integer.parseInt(part);
                if (number < 0 || number > 255) return false;
            } catch (NumberFormatException ignored) {
                return false;
            }
        }
        return true;
    }
}
